	["%s: ¡ya viene!"] = "%s: kommt jetzt!",
	["%s… huele a peligro y a buen botín. Pelea al objetivo que marque tu grupo."] = "%s… riecht nach Gefahr und guter Beute. Greif das Ziel an, das deine Gruppe markiert.",
	["%s… me gusta este lugar."] = "%s… mir gefällt dieser Ort.",
	["(+%d en %s)"] = "(+%d bei %s)",
	["(con %s)"] = "(mit %s)",
	["(con lo del banco: %d más)"] = "(mit dem aus der Bank: %d mehr)",
	["(estimado)"] = "(geschätzt)",
	["(faltan %d)"] = "(%d fehlen)",
	["(la tuya)"] = "(deiner)",
	["(puerta abierta)"] = "(Tür offen)",
	["(puesto)"] = "(angelegt)",
	["(sin comentario)"] = "(kein Kommentar)",
	["(tienes %d)"] = "(du hast %d)",
	["(todavía sin texto: escríbelo arriba)"] = "(noch kein Text: schreib ihn oben)",
	["(tú)"] = "(du)",
	["(vacía)"] = "(leer)",
	["**Mi temporada con la manada** (Alfa, La Jauría)"] = "**Meine Saison mit dem Rudel** (Alfa, La Jauría)",
	["*bosteza* Cazar contigo es lo mejor de mi día."] = "*gähnt* Mit dir zu jagen ist das Schönste an meinem Tag.",
	["*la devora en un segundo* ¡Gracias! Ahora sí, a cazar."] = "*verschlingt es in einer Sekunde* Danke! Jetzt aber auf die Jagd.",
	["*levanta la manita* ¿Salchicha? Prometo cuidarte el doble."] = "*hebt die Pfote* Ein Würstchen? Ich verspreche, doppelt so gut auf dich aufzupassen.",
	["*mueve la cola despacito* Todo bien por aquí."] = "*wedelt langsam mit dem Schwanz* Hier ist alles gut.",
	["*mueve la cola* Aquí sigo, atenta."] = "*wedelt mit dem Schwanz* Ich bin noch da und passe auf.",
	["*mueve la cola* Huelo una salchicha en tu mochila. ¿Me la das?"] = "*wedelt mit dem Schwanz* Ich rieche ein Würstchen in deinem Rucksack. Krieg ich es?",
	["*olfatea el aire* Huele a aventura."] = "*schnuppert in die Luft* Riecht nach Abenteuer.",
	["*olfatea el suelo* Por aquí pasó un jabalí... hace rato."] = "*schnuppert am Boden* Hier ist ein Eber vorbeigekommen... vor einer Weile.",
	["*persigue su cola un ratito* …¡Casi la atrapo!"] = "*jagt kurz ihren Schwanz* …Fast hätte ich ihn!",
	["*se echa un ratito* No estoy dormida, estoy vigilando con los ojos cerrados."] = "*legt sich kurz hin* Ich schlafe nicht, ich halte Wache mit geschlossenen Augen.",
	["*se estira y bosteza* Listo, ¡a seguir!"] = "*streckt sich und gähnt* Gut, weiter!",
	["*se rasca la oreja* Listo, ya me quedé tranquila."] = "*kratzt sich am Ohr* So, jetzt bin ich wieder ruhig.",
	["*se sienta y te mira con ojitos tiernos* ¿Me das una salchicha? Solo una… bueno, una."] = "*setzt sich und schaut dich mit großen Augen an* Krieg ich ein Würstchen? Nur eins… na gut, eins.",
