	["+%s niveles"] = "+%s Stufen",
	[", con %d de habilidad"] = ", mit %d Fertigkeit",
	["... y %d talentos más"] = "... und %d weitere Talente",
	["/alfa enciclopedia abre la ventana; /alfa enciclopedia <texto> busca de una vez."] = "/alfa enciclopedia öffnet das Fenster; /alfa enciclopedia <Text> sucht sofort.",
	["/alfa mapa abre el mapa, /alfa limpio cambia el modo limpio y /alfa mundo abre esta página."] = "/alfa mapa öffnet die Karte, /alfa limpio schaltet den Fokusmodus um und /alfa mundo öffnet diese Seite.",
	["1 = solo aprenderla. Los rangos: 75, 150, 225 y 300."] = "1 = nur erlernen. Die Ränge: 75, 150, 225 und 300.",
	["1 año de aventuras"] = "1 Jahr voller Abenteuer",
	["1 carta"] = "1 Brief",
	["1 casilla"] = "1 Platz",
	["1 da menos XP: para entonces le sacas 6 niveles o más."] = "1 gibt weniger EP: Bis dahin bist du 6 oder mehr Stufen darüber.",
	["1 de tu registro aquí cerca"] = "1 aus deinem Questlog in der Nähe",
	["1 día"] = "1 Tag",
	["1 espacio"] = "1 Platz",
	["1 espacio libre"] = "1 freier Platz",
	["1 fragmento"] = "1 Splitter",
	["1 h"] = "1 Std.",
	["1 habilidad por aprender"] = "1 Fähigkeit zu lernen",
	["1 historia"] = "1 Geschichte",
	["1 historia guardada aquí"] = "1 Geschichte hier gespeichert",
	["1 importado"] = "1 importiert",
	["1 libre"] = "1 frei",
	["1 lista: la flecha te lleva"] = "1 fertig: Der Pfeil führt dich hin",
	["1 lobo"] = "1 Wolf",
	["1 lugar"] = "1 Ort",
	["1 marcador"] = "1 Markierung",
	["1 mejora"] = "1 Upgrade",
	["1 meta"] = "1 Ziel",
	["1 meta de caza o botín sin calcular."] = "1 Kill- oder Beuteziel nicht geschätzt.",
	["1 misión"] = "1 Quest",
	["1 misión entregada"] = "1 Quest abgegeben",
	["1 misión para recoger"] = "1 Quest zum Annehmen",
	["1 misión para tu bando."] = "1 Quest für deine Fraktion.",
	["1 misión que aún no haces."] = "1 Quest, die du noch nicht gemacht hast.",
	["1 muerte"] = "1 Tod",
	["1 más sin XP conocida: no cuenta."] = "1 weitere ohne bekannte EP: Sie zählt nicht.",
	["1 nivel"] = "1 Stufe",
	["1 no se movió: ya no estaba ahí o el juego no lo soltó."] = "1 wurde nicht bewegt: Es war nicht mehr da oder das Spiel hat es nicht freigegeben.",
	["1 objeto"] = "1 Gegenstand",
	["1 objeto más es de un jefe que aún no descubres."] = "1 weiterer Gegenstand stammt von einem Boss, den du noch nicht entdeckt hast.",
	["1 para después"] = "1 für später",
	["1 para recoger"] = "1 zum Annehmen",
	["1 para recoger ahora"] = "1 jetzt zum Annehmen",
	["1 punto libre"] = "1 freier Punkt",
	["1 resultado"] = "1 Ergebnis",
	["1 tótem puesto"] = "1 Totem aufgestellt",
	["1. Abre Hoy en un pueblo y luego en el campo.\nFunciona si: arriba sale lo que más conviene hacer ahí y cambia según dónde estás."] = "1. Öffne Heute in einer Stadt und dann draußen.\nFunktioniert, wenn: oben das Sinnvollste für diesen Ort steht und es sich je nach Ort ändert.",
	["1. Abre la Biblioteca de guías > Profesiones y elige Minería o Herrería.\nFunciona si: ves la mejor zona, qué receta hacer y cuántas, y tus materiales con lo de tus otros personajes descontado."] = "1. Öffne die Leitfadenbibliothek > Berufe und wähle Bergbau oder Schmiedekunst.\nFunktioniert, wenn: du das beste Gebiet, welches Rezept wie oft und deine Materialien abzüglich deiner anderen Charaktere siehst.",
	["1. Abre la página Curación y elige tu especialización.\nFunciona si: el dibujo del ratón dice qué hace cada clic."] = "1. Öffne die Heilungsseite und wähle deine Spezialisierung.\nFunktioniert, wenn: die Mauszeichnung zeigt, was jeder Klick tut.",
	["1. Abre la página La Jauría.\nFunciona si: el marcador de Horda y Alianza tiene números y no sale vacío."] = "1. Öffne die Seite La Jauría.\nFunktioniert, wenn: die Anzeige von Horde und Allianz Zahlen hat und nicht leer ist.",
	["1. Abre las bolsas con un pico de minero o una montura.\nFunciona si: llevan su candado y «Vender grises» no las toca."] = "1. Öffne die Taschen mit einer Spitzhacke oder einem Reittier darin.\nFunktioniert, wenn: sie ihr Schloss tragen und „Graues verkaufen“ sie nicht anrührt.",
	["1. Camina hacia el PNJ de una entrega de tu guía.\nFunciona si: al acercarte, el minimapa lo marca con el signo de entrega y su nombre al pasar el ratón."] = "1. Geh auf den Abgabe-NPC deines Leitfadens zu.\nFunktioniert, wenn: die Minikarte ihn beim Näherkommen mit dem Abgabezeichen markiert und beim Darüberfahren seinen Namen zeigt.",
	["1. Con la flecha a la vista, dale un clic.\nFunciona si: te lleva al siguiente lugar (otro punto de la meta o de tu ruta de recolección)."] = "1. Klicke auf den sichtbaren Pfeil.\nFunktioniert, wenn: er dich zum nächsten Ort bringt (ein anderer Punkt des Ziels oder deiner Sammelroute).",
	["1. Con la ruta de «Cerrar mis misiones» en marcha, entrega una misión.\nFunciona si: sale «¡Lista! Sigue: …», la flecha pasa a la siguiente parada y, al cerrar la última, Lya festeja."] = "1. Gib bei laufender Route „Meine Quests abschließen“ eine Quest ab.\nFunktioniert, wenn: „Erledigt! Weiter: …“ erscheint, der Pfeil zum nächsten Halt wechselt und Lya nach der letzten feiert.",
	["1. Con varias misiones en tu registro, abre Hoy y toca «Cerrar mis misiones».\nFunciona si: al momento sale su avance, luego el resumen, y «Empezar» pone la flecha en la primera parada."] = "1. Öffne mit mehreren Quests im Log „Heute“ und tippe auf „Meine Quests abschließen“.\nFunktioniert, wenn: sofort der Fortschritt erscheint, dann die Übersicht, und „Los“ den Pfeil auf den ersten Halt setzt.",
	["1. Empieza «Cerrar mis misiones».\n2. Abre el mapa del juego (M) y el mapa de Alfa.\nFunciona si: ves las paradas numeradas, unidas con puntitos."] = "1. Starte „Meine Quests abschließen“.\n2. Öffne die Spielkarte (M) und Alfas Karte.\nFunktioniert, wenn: du die nummerierten Halte mit Pünktchen verbunden siehst.",
	["1. En el menú (+) del rastreador elige «Restablecer esta guía».\nFunciona si: te deja en el paso que te toca por tu nivel, tus misiones o tu oficio, y «Deshacer» lo regresa."] = "1. Wähle im (+)-Menü des Trackers „Diesen Leitfaden zurücksetzen“.\nFunktioniert, wenn: du beim passenden Schritt für Stufe, Quests oder Beruf landest und „Rückgängig“ es zurückholt.",
	["1. En el resumen de «Cerrar mis misiones», prende «Al final, a la ciudad: entrenar y vender».\n2. Cierra tu ruta.\nFunciona si: la flecha te lleva a tu entrenador (si tienes algo que aprender) y luego a quien repara."] = "1. Schalte in der Übersicht von „Meine Quests abschließen“ „Am Ende in die Stadt: lernen und verkaufen“ ein.\n2. Schließe deine Route ab.\nFunktioniert, wenn: der Pfeil dich zu deinem Lehrer führt (wenn es etwas zu lernen gibt) und dann zu einem Reparaturhändler.",
	["1. En la ventana de reportes toca «Enviar ya por el navegador».\n2. Copia el enlace y pégalo en tu navegador.\nFunciona si: el formulario abre con todo ya escrito."] = "1. Tippe im Berichtsfenster auf „Jetzt per Browser senden“.\n2. Kopiere den Link und füge ihn im Browser ein.\nFunktioniert, wenn: das Formular schon ausgefüllt öffnet.",
	["1. En plena pelea, pide «Cerrar mis misiones».\nFunciona si: dice que espera a que salgas de combate y sigue sola al terminar, sin errores."] = "1. Fordere mitten im Kampf „Meine Quests abschließen“ an.\nFunktioniert, wenn: es sagt, dass es auf das Kampfende wartet, und danach von selbst weitermacht, ohne Fehler.",
	["1. En una guía de profesión que fabrica, llega al paso de tus materiales.\n2. Toca «Comprar lo que falta».\nFunciona si: tu lista de Comercio tiene lo que te falta, y en la subasta te dice qué buscar."] = "1. Erreiche in einem Herstellungsleitfaden den Schritt mit deinen Materialien.\n2. Tippe auf „Fehlendes kaufen“.\nFunktioniert, wenn: deine Handelsliste das Fehlende enthält und das Auktionshaus dir sagt, wonach du suchen sollst.",
	["1. Entra a una mazmorra y abre su página en Alfa.\nFunciona si: ves el plano por dentro, con sus pisos y tu avance por jefes."] = "1. Betritt einen Dungeon und öffne seine Seite in Alfa.\nFunktioniert, wenn: du die Innenkarte mit Ebenen und deinem Bossfortschritt siehst.",
	["1. Entra a una zona nueva.\nFunciona si: el anuncio dice el rango de niveles correcto y no tapa los textos del juego."] = "1. Betritt ein neues Gebiet.\nFunktioniert, wenn: die Ankündigung den richtigen Stufenbereich zeigt und die Texte des Spiels nicht verdeckt.",
	["1. Escribe /alfa lobos.\nFunciona si: ves quién de tu hermandad usa Alfa, con su versión y quién debe actualizar."] = "1. Tippe /alfa lobos.\nFunktioniert, wenn: du siehst, wer in deiner Gilde Alfa nutzt, mit Version und wer aktualisieren muss.",
	["1. Escribe /alfa recoleccion llevame plata.\nFunciona si: te manda a la zona más probable para tu nivel y tu bando, y te dice por qué."] = "1. Tippe /alfa recoleccion llevame plata.\nFunktioniert, wenn: es dich ins wahrscheinlichste Gebiet für deine Stufe und Fraktion schickt und sagt, warum.",
	["1. Escribe /alfa reportar, escribe algo y toca «Enviar».\n2. Abre el instalador de Alfa (Instalar-Alfa.exe).\nFunciona si: el instalador dice que mandó tu reporte."] = "1. Tippe /alfa reportar, schreib etwas und tippe auf „Senden“.\n2. Öffne Alfas Installationsprogramm (Instalar-Alfa.exe).\nFunktioniert, wenn: das Installationsprogramm meldet, dass dein Bericht gesendet wurde.",
	["1. Haz algo que dé el mismo aviso varias veces (por ejemplo, entregar misiones seguidas).\nFunciona si: los avisos iguales se callan solos y los distintos sí salen."] = "1. Tu etwas, das mehrmals denselben Hinweis auslöst (z. B. mehrere Quests nacheinander abgeben).\nFunktioniert, wenn: gleiche Hinweise von selbst verstummen und andere weiter erscheinen.",
	["1. Llega a un paso de entregar una misión que te deja elegir recompensa.\nFunciona si: el rastreador dice «Elige: …» con una pieza que te sirve, la misma que marca la ventana de la misión."] = "1. Erreiche einen Abgabeschritt einer Quest mit Belohnungswahl.\nFunktioniert, wenn: der Tracker „Wähle: …“ mit einem passenden Teil zeigt, demselben, das das Questfenster markiert.",
	["1. Llega al nivel 40. La montura y la equitación se compran a la vez: junta el oro mientras subes."] = "1. Erreiche Stufe 40. Reittier und Reitfertigkeit kaufst du zusammen: Spar beim Leveln Gold an.",
	["1. Pelea con un jefe de mazmorra.\nFunciona si: salen los avisos de jefes del juego. Forever podría no traerlos: si no salen, elige «No funciona»."] = "1. Kämpfe gegen einen Dungeonboss.\nFunktioniert, wenn: die Bosswarnungen des Spiels erscheinen. Forever hat sie vielleicht nicht: Wenn nicht, wähle „Funktioniert nicht“.",
	["1. Pelea un par de veces y abre la página Combate.\nFunciona si: ves tus últimas peleas con su resumen."] = "1. Kämpfe ein paarmal und öffne die Kampfseite.\nFunktioniert, wenn: du deine letzten Kämpfe mit Zusammenfassung siehst.",
	["1. Pesca unos peces y abre la página Pesca.\nFunciona si: tus récords dicen la fecha y el lugar."] = "1. Fang ein paar Fische und öffne die Angelseite.\nFunktioniert, wenn: deine Rekorde Datum und Ort zeigen.",
	["1. Pon Alfa en coreano o en chino y espera unos avisos.\nFunciona si: ningún aviso sale cortado ni se sale de su caja."] = "1. Stell Alfa auf Koreanisch oder Chinesisch und warte auf einige Hinweise.\nFunktioniert, wenn: kein Hinweis abgeschnitten wird oder aus seinem Kasten ragt.",
	["1. Prende la temática por bando en Ajustes > Estilo y sonido.\nFunciona si: Alfa se viste de tu bando y todos los textos se leen bien."] = "1. Schalte das Fraktionsthema in Einstellungen > Stil und Klang ein.\nFunktioniert, wenn: Alfa die Farben deiner Fraktion trägt und alle Texte gut lesbar sind.",
	["1. Párate en la entrada de una mazmorra con tu grupo.\nFunciona si: la lista «Antes de entrar» se marca sola (grupo, reparar, comida)."] = "1. Stell dich mit deiner Gruppe an einen Dungeoneingang.\nFunktioniert, wenn: die Liste „Vor dem Betreten“ sich selbst abhakt (Gruppe, Reparatur, Essen).",
	["1. Sal de la mazmorra y camina por una zona normal.\nFunciona si: Alfa ya no dice que sigues en una mazmorra (ni el rastreador ni Hoy)."] = "1. Verlasse den Dungeon und lauf durch ein normales Gebiet.\nFunktioniert, wenn: Alfa nicht mehr sagt, dass du in einem Dungeon bist (weder Tracker noch Heute).",
	["1. Sigue la flecha dentro de una mazmorra y durante una pelea.\nFunciona si: no sale ningún error de Alfa y la flecha sigue diciendo la distancia."] = "1. Folge dem Pfeil in einem Dungeon und während eines Kampfes.\nFunktioniert, wenn: kein Alfa-Fehler erscheint und der Pfeil weiter die Entfernung zeigt.",
	["1. Sigue una guía que vaya atrás de tu nivel (por ejemplo, una zona que ya pasaste).\nFunciona si: el rastreador te ofrece «Saltar a mi nivel» y te deja en la parte que te toca."] = "1. Folge einem Leitfaden, der deiner Stufe hinterherhinkt (z. B. ein Gebiet, das du schon hinter dir hast).\nFunktioniert, wenn: der Tracker „Zu meiner Stufe springen“ anbietet und dich zum passenden Teil bringt.",
	["1. Sigue una ruta de recolección y llega a un punto vacío.\nFunciona si: dice «Aquí no hay ahora; voy al siguiente» y la flecha pasa sola al que sigue."] = "1. Folge einer Sammelroute und erreiche einen leeren Punkt.\nFunktioniert, wenn: „Hier ist gerade nichts; weiter zum nächsten“ erscheint und der Pfeil von selbst weiterzieht.",
	["1. Toma misiones hasta tener 18 de 20 en tu registro.\nFunciona si: sale un aviso con «Ver cuáles» que sugiere grises o lejanas para soltar (nunca una lista para entregar)."] = "1. Nimm Quests an, bis du 18 von 20 im Log hast.\nFunktioniert, wenn: ein Hinweis mit „Welche?“ graue oder ferne Quests zum Abbrechen vorschlägt (nie eine abgabebereite).",
	["1. Usa tu piedra de hogar y abre las bolsas.\nFunciona si: el tiempo de recarga cabe en la casilla, sin cortarse ni encimarse."] = "1. Benutze deinen Ruhestein und öffne die Taschen.\nFunktioniert, wenn: die Abklingzeit in den Platz passt, ohne abgeschnitten oder überlagert zu sein.",
	["1. Ve a un muelle o a una torre de zepelín y espera el transporte.\nFunciona si: sale la tarjeta de Alfa con la cuenta de la salida, la ruta y su momento (muelle, a bordo, llegando)."] = "1. Geh zu einem Anleger oder Zeppelinturm und warte auf das Transportmittel.\nFunktioniert, wenn: Alfas Karte den Abfahrts-Countdown, die Route und die Phase zeigt (Anleger, an Bord, Ankunft).",
	["10 segundos después de la pelea se atenúa más; al pasar el ratón vuelve."] = "10 Sekunden nach dem Kampf wird er blasser; mit der Maus darüber kommt er zurück.",
	["1920 × 1200 o 2560 × 1600."] = "1920 × 1200 oder 2560 × 1600.",
	["2 h"] = "2 Std.",
	["2. Ve con el instructor de equitación de tu raza y aprende la de aprendiz."] = "2. Geh zum Reitlehrer deines Volkes und lerne Reiten (Lehrling).",
	["3 de XP, 3 de oro, 3 de XP, 20 de tu profesión y 3 de clase para un objeto único."] = "3 für EP, 3 für Gold, 3 für EP, 20 deines Berufs und 3 deiner Klasse für einen einzigartigen Gegenstand.",
	["3. Compra la montura con el vendedor de tu raza (al lado del instructor) y úsala para aprenderla."] = "3. Kauf das Reittier beim Händler deines Volkes (neben dem Lehrer) und benutze es, um es zu erlernen.",
	["30 min"] = "30 Min.",
	["30 min de calma"] = "30 Min. Ruhe",
	["4. A nivel 60, el mismo instructor enseña la de oficial y el vendedor tiene las rápidas."] = "4. Auf Stufe 60 lehrt derselbe Lehrer Reiten (Geselle), und der Händler hat die schnellen Reittiere.",
	["7 días"] = "7 Tage",
	["<jugador>"] = "<Spieler>",
	["<tu personaje>"] = "<dein Charakter>",
	["<tu reino>"] = "<dein Realm>",
	["A %d yd está %s. Háblale al maestro de vuelo para aprender el vuelo: luego te ahorra el camino."] = "%d yd entfernt ist %s. Sprich mit dem Flugmeister, um die Route zu lernen: Später sparst du dir den Weg.",
	["A %s"] = "%s entfernt",
	["A %s le queda poco"] = "%s läuft bald ab",
	["A %s, %s"] = "%s %s",
	["A Entrañas se baja por elevadores desde las ruinas de la capital de Lordaeron."] = "Nach Unterstadt fährt man mit Aufzügen hinunter, aus den Ruinen der Hauptstadt Lordaerons.",
	["A Mis planes"] = "Zu „Meine Pläne“",
	["A Ragnaros no le gusta que lo despierten antes de tiempo, y su mayordomo Executus lo paga caro."] = "Ragnaros mag es nicht, zu früh geweckt zu werden, und sein Majordomus Exekutus muss teuer dafür bezahlen.",
	["A Silithus se entra desde el Cráter de Un'Goro."] = "Nach Silithus kommt man vom Krater von Un'Goro aus.",
	["A bordo"] = "An Bord",
	["A cualquier lugar: vuelos, barcos, zepelines, portales y a pie."] = "Überallhin: Flüge, Schiffe, Zeppeline, Portale und zu Fuß.",
	["A distancia"] = "Fernkampf",
	["A entregar tus misiones"] = "Auf zur Abgabe deiner Quests",
	["A estas horas hasta los murlocs duermen. No te desveles mucho, que mañana también se caza."] = "Um diese Zeit schlafen sogar die Murlocs. Bleib nicht zu lange auf, morgen wird auch gejagt.",
	["A la derecha"] = "Rechts",
	["A la entrada de Ventormenta, estatuas de los grandes héroes de la Segunda Guerra reciben a los visitantes."] = "Am Eingang von Sturmwind begrüßen Statuen der großen Helden des Zweiten Krieges die Besucher.",
	["A la izquierda"] = "Links",
	["A la izquierda de tus marcos, tu hechizo de apoyo con cuántos no lo tienen; al pasar el ratón, quiénes. Fuera de combate."] = "Links neben deinen Rahmen dein Unterstützungszauber mit der Zahl derer, denen er fehlt; beim Überfahren, wer. Außerhalb des Kampfes.",
	["A la medida"] = "Eigene",
	["A la torre"] = "Zum Turm",
	["A la vista: %d de la manada · %d de tu grupo"] = "In Sicht: %d aus dem Rudel · %d aus deiner Gruppe",
	["A las demás les dice qué les falta: tu nivel o una misión antes."] = "Bei den anderen steht, was ihnen fehlt: deine Stufe oder eine Quest davor.",
	["A los lados del modelo, un botón por ranura: un clic oculta esa pieza y otro la vuelve a poner."] = "Neben dem Modell gibt es einen Knopf pro Platz: Ein Klick blendet das Teil aus, ein weiterer legt es wieder an.",
	["A mi lista"] = "Auf meine Liste",
	["A mi lista de compras"] = "Auf meine Einkaufsliste",
	["A mitad de la pelea aparecen espectros de hielo: mátenlos rápido o usen ataques en área."] = "Mitten im Kampf erscheinen Frostgeister: Tötet sie schnell oder nutzt Flächenangriffe.",
	["A mitad de la pelea se protege con un escudo y prepara una gran explosión: cuando lo veas brillar, ¡aléjate de él!"] = "Mitten im Kampf schützt er sich mit einem Schild und lädt eine große Explosion auf: Wenn er leuchtet, geh weg von ihm!",
	["A nivel 10 haces las misiones para domar a tu primera mascota."] = "Auf Stufe 10 machst du die Quests, um deinen ersten Begleiter zu zähmen.",
	["A nivel 20 aprendes Lobo fantasmal: ¡te vuelves un lobo como yo! Corre, que te echo una carrera."] = "Auf Stufe 20 lernst du Geisterwolf: Du wirst ein Wolf wie ich! Komm, wir laufen um die Wette.",
	["A nivel 60 sigue la rápida: equitación de oficial y una montura épica."] = "Auf Stufe 60 folgt das schnelle: Reiten (Geselle) und ein episches Reittier.",
	["A pedido"] = "Auf Wunsch",
	["A pelear"] = "Kampfbereit",
	["A pescar"] = "Los, angeln",
	["A pie son unos %s; con el vuelo, unos %s."] = "Zu Fuß etwa %s; mit dem Flug etwa %s.",
	["A probar"] = "Ausprobieren",
	["A quién ir"] = "Zu wem gehen",
	["A su entrenador"] = "Zu seinem Lehrer",
	["A tu anuncio: «%s»."] = "Zu deiner Anzeige: „%s“.",
	["A tu gusto"] = "Nach deinem Geschmack",
	["A tu lado"] = "An deiner Seite",
	["A tu medida"] = "Nach deinem Geschmack",
	["A tu nivel"] = "Auf deiner Stufe",
	["A tu nivel los enemigos caen rápido: remata con 3 puntos de combo."] = "Auf deiner Stufe fallen Gegner schnell: Beende mit 3 Combopunkten.",
	["A tu nivel te conviene %s: lo vende el posadero o un vendedor de comida."] = "Für deine Stufe lohnt sich %s: Gastwirte und Essensverkäufer haben es.",
	["A tu nivel: %s"] = "Für deine Stufe: %s",
	["A tu ritmo de esta sesión: %s de experiencia por hora."] = "Bei deinem Tempo in dieser Sitzung: %s Erfahrung pro Stunde.",
	["A un clic"] = "Mit einem Klick",
	["A veces"] = "Manchmal",
	["A veces el golpe ni te toca."] = "Manchmal trifft dich der Schlag gar nicht.",
	["A veces el juego tarda o no deja mover a nadie más a esa capa. Puedes salir del grupo y probar con otra."] = "Manchmal dauert es, oder das Spiel lässt niemanden mehr auf diese Ebene. Du kannst die Gruppe verlassen und einen anderen versuchen.",
	["A veces pescas cajas y botellas con mensajes que empiezan una misión."] = "Manchmal angelst du Kisten und Flaschen mit Botschaften, die eine Quest starten.",
	["A veces salen gemas al minar: guárdalas, porque varias profesiones las usan en sus recetas."] = "Beim Bergbau springen manchmal Edelsteine heraus: Heb sie auf, denn mehrere Berufe brauchen sie für ihre Rezepte.",
	["Abajo"] = "Unten",
	["Abajo del modelo, elige lo que hace tu personaje (caminar, bailar, saludar...) y páusalo."] = "Unter dem Modell wählst du, was dein Charakter tut (gehen, tanzen, winken...), und kannst es pausieren.",
	["Abajo va su camino de jefes, marcado con lo que ya vencieron."] = "Unten siehst du den Weg der Bosse, mit den bereits besiegten markiert.",
	["Abajo y al centro del ícono, con letra que crece con él. Apagada, chiquita en la esquina."] = "Unten in der Mitte des Symbols, mit einer Schrift, die mitwächst. Aus: klein in der Ecke.",
	["Abalorio"] = "Schmuck",
	["Abalorios"] = "Schmuckstücke",
	["Abandonar"] = "Abbrechen",
	["Abandonar marcadas (%d)"] = "Markierte abbrechen (%d)",
	["Abandonar misión"] = "Quest abbrechen",
	["Abandonar una misión…"] = "Eine Quest abbrechen…",
	["Abandonaste %d misiones"] = "Du hast %d Quests abgebrochen",
	["Abandonaste %d misión"] = "Du hast %d Quest abgebrochen",
	["Abierta"] = "Offen",
	["Abierta: si alguien de la manada pide entrar, Alfa lo invita a tu grupo (fuera de combate)."] = "Offen: Wenn jemand aus dem Rudel hinein will, lädt Alfa ihn in deine Gruppe ein (außerhalb des Kampfes).",
	["Abiertas"] = "Geöffnet",
	["Abrazo vampírico: tu daño de sombras te cura."] = "Vampirumarmung: Dein Schattenschaden heilt dich.",
	["Abre %d misiones más"] = "Öffnet %d weitere Quests",
	["Abre %d misión más"] = "Öffnet %d weitere Quest",
	["Abre Heridas profundas."] = "Öffnet Tiefe Wunden.",
	["Abre Hoy: ahí te digo lo más útil para este momento en grande, y tu camino a un par de clics."] = "Öffne Heute: Dort zeige ich dir groß, was gerade am nützlichsten ist, und deinen Weg ein paar Klicks entfernt.",
	["Abre Paisaje y gráficos"] = "Öffnet Landschaft und Grafik",
	["Abre Recolección. Con «ruta», crea y sigue una ruta para juntar en tu zona."] = "Öffnet Sammeln. Mit «ruta» erstellst du eine Sammelroute in deiner Zone und folgst ihr.",
	["Abre desde el sigilo para empezar con ventaja."] = "Greif aus der Verstohlenheit an, um mit Vorteil zu beginnen.",
	["Abre el buzón en la pestaña «Enviar» y vuelve a darle a «Mandar a %s»."] = "Öffne den Briefkasten auf dem Reiter „Senden“ und klicke erneut auf „An %s senden“.",
	["Abre el mapa de Alfa con su camino entero. Si no es la que sigues, primero la sigue."] = "Öffnet Alfas Karte mit der ganzen Route. Wenn du ihr gerade nicht folgst, folgst du ihr zuerst.",
	["Abre el mapa de Alfa encuadrado donde apunta la flecha, con el camino de tu guía."] = "Öffnet Alfas Karte dort, wo der Pfeil hinzeigt, mit dem Weg deines Leitfadens.",
	["Abre el mapa del juego en esta misma zona. En combate el mapa del juego no se abre desde Alfa."] = "Öffnet die Karte des Spiels in diesem Gebiet. Im Kampf öffnet sich die Spielkarte nicht über Alfa.",
	["Abre el mapa y haz clic derecho (o Mayús+clic) donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras. En el mapa del juego, Mayús+clic derecho."] = "Öffne die Karte und mach einen Rechtsklick (oder Umschalt+Klick), wo du eine willst: Gib ihr Namen, Symbol und Farbe, und der Pfeil führt dich hin, wann du willst. Auf der Spielkarte: Umschalt+Rechtsklick.",
	["Abre el mapa: cada muelle dice cuánto falta para que llegue su barco o zepelín."] = "Öffne die Karte: Jeder Anleger zeigt, wie lange es dauert, bis sein Schiff oder Zeppelin ankommt.",
	["Abre el modo pesca (aquí, con /alfa pesca o al ponerte la caña) y pulsa %s: tu tecla te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "Öffne den Angelmodus (hier, mit /alfa pesca oder beim Anlegen der Angel) und drück %s: Deine Taste legt dir die Ausrüstung an, bringt den Köder an, wirft aus und holt ein, wenn es platscht.",
	["Abre el modo pesca y elige tu tecla: te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "Öffne den Angelmodus und wähl deine Taste: Sie legt dir die Ausrüstung an, bringt den Köder an, wirft aus und holt ein, wenn es platscht.",
	["Abre el modo pesca y pulsa tu tecla: lo que saques aparece aquí."] = "Öffne den Angelmodus und drück deine Taste: Was du fängst, erscheint hier.",
	["Abre la Cocina del juego (el botón lo hace) y vuelve a pulsar."] = "Öffne das Kochkunst-Fenster des Spiels (der Button macht das) und drück noch einmal.",
	["Abre la Enciclopedia y en la ficha del objeto toca «Agregar a mi ruta»."] = "Öffne die Enzyklopädie und klick im Eintrag des Gegenstands auf „Zu meiner Route hinzufügen“.",
	["Abre la casa de subastas para escanear."] = "Öffne das Auktionshaus zum Scannen.",
	["Abre la casa de subastas y pulsa «Escanear con Alfa» para saber cuánto valen tus objetos."] = "Öffne das Auktionshaus und drück „Mit Alfa scannen“, um zu erfahren, was deine Gegenstände wert sind.",
	["Abre la guía de Alfa que te lleva a conseguir este objeto."] = "Öffnet den Alfa-Guide, der dich zu diesem Gegenstand führt.",
	["Abre la guía de subir de nivel de esta zona que mejor te queda."] = "Öffnet den Stufenleitfaden dieser Zone, der am besten zu dir passt.",
	["Abre la pelea a distancia antes de que llegue."] = "Eröffne den Kampf auf Distanz, bevor er dich erreicht.",
	["Abre la pelea: te acerca al enemigo y te da ira."] = "Eröffnet den Kampf: bringt dich zum Gegner und gibt dir Wut.",
	["Abre la pestaña «Enviar» del buzón."] = "Öffne den Reiter «Senden» des Briefkastens.",
	["Abre la siguiente fila."] = "Öffnet die nächste Reihe.",
	["Abre la ventana Historias."] = "Öffnet das Fenster Geschichten.",
	["Abre la ventana de clic para lanzar de Blizzard para que armes ahí los mismos clics y cures igual en sus marcos de grupo (el juego no deja que un addon los copie)."] = "Öffnet Blizzards Fenster für Klickzauber, damit du dort dieselben Klicks einrichtest und in seinen Gruppenrahmen genauso heilst (das Spiel lässt ein Addon sie nicht kopieren).",
	["Abre la ventana de talentos del juego una vez o espera unos segundos: en cuanto Alfa la lea, te dice qué poner. Mientras, abajo ves tu build."] = "Öffne einmal das Talentfenster des Spiels oder warte ein paar Sekunden: Sobald Alfa es liest, sagt es dir, was du nehmen sollst. Unten siehst du so lange deinen Build.",
	["Abre la ventana de talentos del juego una vez o espera unos segundos: en cuanto Alfa la lea, te dice qué poner. Mientras, abajo ves tu plan de talentos."] = "Öffne einmal das Talentfenster des Spiels oder warte ein paar Sekunden: Sobald Alfa es liest, sagt es dir, was du nehmen sollst. Unten siehst du so lange deinen Build.",
	["Abre la ventana de tu profesión una vez y Alfa leerá tus recetas para decirte cuáles te dejan ganancia."] = "Öffne einmal das Fenster deines Berufs, dann liest Alfa deine Rezepte und sagt dir, welche Gewinn bringen.",
	["Abre la ventana principal de Alfa."] = "Öffnet das Hauptfenster von Alfa.",
	["Abre o cierra el mapa de Alfa"] = "Öffnet oder schließt Alfas Karte",
	["Abre siempre con Cargar y pon Desgarrar al empezar la pelea."] = "Eröffne immer mit Sturmangriff und setz zu Kampfbeginn Verwunden.",
	["Abre siempre desde el sigilo con tu ataque más fuerte."] = "Eröffne immer aus der Verstohlenheit mit deinem stärksten Angriff.",
	["Abre su ficha en Mazmorras y toca «Guíame»: la flecha te lleva hasta la puerta, aunque esté escondida en una cueva."] = "Öffne seine Seite in Dungeons und tippe auf „Führ mich hin“: Der Pfeil bringt dich bis zur Tür, auch wenn sie in einer Höhle versteckt ist.",
	["Abre su ficha."] = "Öffnet den Eintrag.",
	["Abre tus bolsas con su tecla o con el botón de la mochila."] = "Öffne deine Taschen mit ihrer Taste oder dem Rucksack-Knopf.",
	["Abre tus bolsas con tu tecla (%s)."] = "Öffne deine Taschen mit deiner Taste (%s).",
	["Abre un buzón para tomar tus cartas."] = "Öffne einen Briefkasten, um deine Post zu nehmen.",
	["Abre un susurro con tu mensaje listo. Si no está conectado, el juego te lo dirá."] = "Öffnet ein Flüstern mit deiner fertigen Nachricht. Ist die Person offline, sagt dir das Spiel Bescheid.",
	["Abre una guía o arma tu plan y aquí lo sigues."] = "Öffne einen Guide oder bau deinen Plan, und hier folgst du ihm.",
