	["Compra"] = "Kauf",
	["Compra lo que tu paso necesita si el comerciante lo vende. Nada de más de 50 de oro."] = "Kauft, was dein Schritt braucht, wenn der Händler es verkauft. Nichts über 50 Gold.",
	["Compra tu montura con %s"] = "Kauf dein Reittier bei %s",
	["Comprar"] = "Kaufen",
	["Comprar comida y bebida"] = "Essen und Trinken kaufen",
	["Comprar lo que falta"] = "Fehlendes kaufen",
	["Comprar lo que falta cuesta más de %s (faltan precios)."] = "Was fehlt, kostet mehr als %s (Preise fehlen).",
