	["Modo foco"] = "Fokusmodus",
	["Modo historia"] = "Storymodus",
	["Modo historia: %d jefes por descubrir. Vence a cada uno para ver su nombre y su botín (puedes apagarlo en Ajustes)."] = "Storymodus: %d Bosse zu entdecken. Besiege jeden, um seinen Namen und seine Beute zu sehen (du kannst das in den Einstellungen ausschalten).",
	["Modo historia: %d jefes por descubrir. Vence a cada uno para ver su nombre y su botín."] = "Storymodus: %d Bosse zu entdecken. Besiege jeden, um seinen Namen und seine Beute zu sehen.",
	["Modo historia: 1 jefe por descubrir. Vence a cada uno para ver su nombre y su botín (puedes apagarlo en Ajustes)."] = "Storymodus: 1 Boss zu entdecken. Besiege jeden, um seinen Namen und seine Beute zu sehen (du kannst das in den Einstellungen ausschalten).",
	["Modo historia: 1 jefe por descubrir. Vence a cada uno para ver su nombre y su botín."] = "Storymodus: 1 Boss zu entdecken. Besiege jeden, um seinen Namen und seine Beute zu sehen.",
	["Modo ligero"] = "Leichter Modus",
	["Modo limpio"] = "Fokusmodus",
	["Modo limpio apagado: tus capas volvieron como estaban."] = "Fokusmodus aus: Deine Ebenen sind wieder wie vorher.",
	["Modo limpio encendido: solo tú, tu grupo, tus marcadores y la guía."] = "Fokusmodus an: nur du, deine Gruppe, deine Markierungen und der Guide.",
	["Modo limpio: solo tú, tu grupo, tus marcadores y la guía"] = "Fokusmodus: nur du, deine Gruppe, deine Markierungen und der Guide",
