	["Nodos en el mapa del mundo: ocultos."] = "Punkte auf der Weltkarte: ausgeblendet.",
	["Nodos en el mapa del mundo: visibles."] = "Punkte auf der Weltkarte: sichtbar.",
	["Nodos en el minimapa: ocultos."] = "Punkte auf der Minikarte: ausgeblendet.",
	["Nodos en el minimapa: visibles."] = "Punkte auf der Minikarte: sichtbar.",
	["Nodos ocultos."] = "Vorkommen ausgeblendet.",
