	["Ocultar los detalles"] = "Details ausblenden",
	["Ocultar los grifos de la barra de acción"] = "Greifen der Aktionsleiste ausblenden",
	["Ocultar los marcos de grupo de Blizzard"] = "Gruppenrahmen von Blizzard ausblenden",
	["Ocultar nombres al pescar"] = "Namen beim Angeln ausblenden",
	["Ocultar objetos chicos lejanos"] = "Kleine entfernte Objekte ausblenden",
	["Ocultarlo en combate"] = "Im Kampf ausblenden",
	["Ocultas"] = "Verborgen",
	["Ocultas como en el juego, reveladas, o reveladas con un tono más frío para saber dónde no has estado."] = "Verborgen wie im Spiel, aufgedeckt oder aufgedeckt mit kühlerem Farbton, damit du weißt, wo du noch nicht warst.",
	["Oculto en el modelo."] = "Am Modell ausgeblendet.",
