	["Tu entrenador: %s."] = "Dein Lehrer: %s.",
	["Tu equipo está al %d %%: repara antes de entrar"] = "Deine Ausrüstung ist bei %d %%: Repariere vor dem Betreten",
	["Tu equipo está al %d%%. Mejor repararlo antes de la siguiente pelea."] = "Deine Ausrüstung ist bei %d%%. Besser vor dem nächsten Kampf reparieren.",
	["Tu equipo está por romperse"] = "Deine Ausrüstung geht gleich kaputt",
