	["XP/h"] = "EP/h",
	["XP/h: aún no"] = "EP/h: noch nicht",
	["Y %d más"] = "Und %d weitere",
	["Y %d piezas más necesitan reparación."] = "Und %d weitere Teile müssen repariert werden.",
	["Y 1 pieza más necesita reparación."] = "Und 1 weiteres Teil muss repariert werden.",
	["Y aquí estoy yo"] = "Und hier bin ich",
	["Y la tuya tampoco se queda atrás, ¿eh?"] = "Und deine steht ihr in nichts nach, oder?",
	["Y sin caer ni una vez. ¡Qué manada!"] = "Und ohne ein einziges Mal zu fallen. Was für ein Rudel!",
	["Y tu plan «%s»."] = "Und deinen Plan „%s“.",
	["Y una prueba nueva que juega Alfa de punta a punta antes de cada versión, para que estos errores no regresen."] = "Und ein neuer Test, der Alfa vor jeder Version von vorn bis hinten durchspielt, damit diese Fehler nicht zurückkommen.",
	["Ya casi llegamos: %s"] = "Gleich da: %s",
	["Ya casi no cabe nada: %d libres. Lo gris es oro fácil con cualquier vendedor."] = "Es passt kaum noch etwas rein: %d frei. Graues ist leichtes Gold bei jedem Händler.",
	["Ya cuidas a 3 aprendices: termina con alguno para adoptar otro."] = "Du kümmerst dich schon um 3 Schützlinge: Beende einen, um einen weiteren zu adoptieren.",
	["Ya dijiste: %s"] = "Deine Antwort: %s",
	["Ya entendí"] = "Verstanden",
	["Ya eres nivel %d y esta parte de la guía es para llegar al %d. La que te toca empieza en el paso %d: %s."] = "Du bist schon Stufe %d, und dieser Teil ist für Stufe %d. Dein Teil beginnt bei Schritt %d: %s.",
	["Ya eres nivel %d: lo que falta de esta guía es para llegar al %d. Lo que sigue para tu nivel: %s."] = "Du bist schon Stufe %d: Der Rest dieses Leitfadens ist für Stufe %d. Als Nächstes für deine Stufe: %s.",
	["Ya es de madrugada, lobo. Una misión más y a dormir, ¿sí? Azeroth sigue aquí mañana."] = "Es ist schon tiefe Nacht, Wolf. Noch eine Quest und ab ins Bett, ja? Azeroth ist morgen auch noch da.",
	["Ya es de madrugada… buenas noches, lobo. Si sigues, yo te cuido despacito."] = "Es ist schon tief in der Nacht… gute Nacht, Wolf. Wenn du weitermachst, passe ich leise auf dich auf.",
	["Ya es de noche. Una buena cacería antes de dormir y luego a descansar."] = "Es ist schon Nacht. Noch eine gute Jagd vor dem Schlafen, und dann ausruhen.",
	["Ya es tu aprendiz."] = "Er ist schon dein Schützling.",
	["Ya está"] = "Hinzugefügt",
	["Ya está en tu registro"] = "Schon in deinem Questlog",
	["Ya está seleccionada: cópiala con Ctrl+C (Cmd+C en Mac) y pégala donde importes escalas, o compártela."] = "Schon markiert: Kopiere ihn mit Strg+C (Cmd+C auf dem Mac) und füge ihn dort ein, wo du Skalen importierst, oder teile ihn.",
	["Ya está seleccionado: Ctrl+C para copiar y pégalo en Discord. No lleva tu nombre ni tu reino."] = "Schon markiert: Strg+C zum Kopieren, dann in Discord einfügen. Ohne deinen Namen und dein Reich.",
	["Ya está seleccionado: cópialo con Ctrl+C y luego presiona Esc. Nada se envía."] = "Es ist schon markiert: Kopiere es mit Strg+C und drücke dann Esc. Nichts wird gesendet.",
	["Ya estás dentro"] = "Du bist schon drin",
	["Ya estás en esa guarida."] = "Du bist schon in diesem Bau.",
	["Ya estás en la %s: ¿salimos del grupo?"] = "Du bist jetzt in der %s: Verlassen wir die Gruppe?",
	["Ya estás tocando a una puerta. Espera tantito."] = "Du klopfst schon an eine Tür. Warte kurz.",
	["Ya hay %d calladas."] = "Schon %d stummgeschaltet.",
	["Ya hay 1 callada."] = "Schon 1 stummgeschaltet.",
	["Ya la completaste"] = "Schon abgeschlossen",
	["Ya la habías hecho"] = "Schon vorher gemacht",
	["Ya la hice"] = "Erledigt",
	["Ya la hice antes"] = "Hab ich schon gemacht",
	["Ya la hiciste"] = "Schon erledigt",
	["Ya la hiciste."] = "Du hast sie schon erledigt.",
	["Ya la sabes"] = "Schon bekannt",
	["Ya la sabes: Alfa la vio en tu ventana de oficio y sale más barata por punto."] = "Du kennst es schon: Alfa hat es in deinem Berufsfenster gesehen, und es ist pro Punkt billiger.",
	["Ya la superaste"] = "Schon überlevelt",
	["Ya la terminaste: entrégala dentro de la mazmorra."] = "Du hast sie abgeschlossen: Gib sie im Dungeon ab.",
	["Ya la tienes"] = "Du hast es schon",
	["Ya la tienes: entrégala a %s."] = "Du hast sie: Gib sie bei %s ab.",
	["Ya la tienes: tu guía te lleva a entregarla."] = "Du hast sie: Dein Guide führt dich hin, um sie abzugeben.",
	["Ya le preguntaste a la manada hace poco. Te aviso si alguien abre su guarida."] = "Du hast das Rudel gerade erst gefragt. Ich sage dir Bescheid, wenn jemand seinen Bau öffnet.",
	["Ya llamaste a la manada hace un momento. Espera un poco."] = "Du hast das Rudel gerade erst gerufen. Warte ein wenig.",
	["Ya llegaste"] = "Du bist da",
	["Ya llevas %d de sus misiones: te llevo a la entrada."] = "Du hast schon %d seiner Quests: Ich bringe dich zum Eingang.",
	["Ya llevas 1 de sus misiones: te llevo a la entrada."] = "Du hast schon 1 seiner Quests: Ich bringe dich zum Eingang.",
	["Ya llevas puesto «%s»."] = "Du trägst „%s“ schon.",
	["Ya lo guardé. Si lo reportas, nos ayudas a arreglarlo más rápido."] = "Ich habe ihn schon gespeichert. Wenn du ihn meldest, hilfst du uns, ihn schneller zu beheben.",
	["Ya lo tienes"] = "Hast du schon",
	["Ya no"] = "Nicht mehr",
	["Ya no aplica"] = "Nicht mehr offen",
	["Ya no cabe otra: quita las que ya no uses para abrir una nueva."] = "Kein Platz für einen weiteren: entferne die, die du nicht mehr nutzt, um einen neuen zu öffnen.",
	["Ya no da XP"] = "Gibt keine EP mehr",
	["Ya no da experiencia"] = "Gibt keine Erfahrung mehr",
	["Ya no da experiencia (estás en el nivel máximo)"] = "Gibt keine Erfahrung mehr (du bist auf Höchststufe)",
	["Ya no eres aprendiz"] = "Kein Lehrling mehr",
	["Ya no está en esa guarida."] = "Er ist nicht mehr in diesem Bau.",
	["Ya no está en tu registro"] = "Nicht mehr in deinem Questlog",
	["Ya no está en «Recompra»"] = "Nicht mehr im „Rückkauf“",
	["Ya no está sobre un cuadro negro: la acompañan una sombra suave y una elipse del color de tu estilo."] = "Kein schwarzer Kasten mehr hinter ihr: Ein sanfter Schatten und eine Ellipse in der Farbe deines Stils begleiten sie.",
	["Ya no hay nada más que aprender. ¡Qué orgullo!"] = "Es gibt nichts mehr zu lernen. Ich bin so stolz!",
	["Ya no ponérmelo al salir de combate"] = "Nach Kämpfen nicht mehr anlegen",
	["Ya no queda nada por hacer aquí. Elige qué sigue y la manada va contigo."] = "Hier gibt es nichts mehr zu tun. Wähle, was als Nächstes kommt, und das Rudel geht mit dir.",
	["Ya no se consigue"] = "Nicht mehr erhältlich",
	["Ya no se consiguen"] = "Nicht mehr erhältlich",
	["Ya no se puede deshacer"] = "Das lässt sich nicht mehr rückgängig machen",
	["Ya no sigues la ruta de %s: la flecha vuelve a tu guía."] = "Du folgst der Route von %s nicht mehr: Der Pfeil kehrt zu deinem Leitfaden zurück.",
	["Ya no te cabe otra. Te digo cuáles soltar: las que menos te sirven ahora."] = "Es passt keine mehr hinein. Ich sage dir, welche du aufgeben kannst: die, die dir gerade am wenigsten helfen.",
	["Ya no te cambio el equipo al salir de combate."] = "Ich wechsle deine Ausrüstung nach Kämpfen nicht mehr.",
	["Ya no te da experiencia: suéltala o métela si quieres"] = "Gibt dir keine Erfahrung mehr: gib sie auf oder füge sie hinzu, wenn du willst",
	["Ya no te dan casi experiencia y no abren nada que valga la pena. Abandónalas para tener espacio en tu registro."] = "Sie bringen kaum noch Erfahrung und schalten nichts Lohnendes frei. Brich sie ab, um Platz in deinem Questlog zu haben.",
	["Ya no te queda ninguna casilla libre."] = "Du hast keinen freien Platz mehr.",
	["Ya no te quedan cebos que puedas usar. Los venden los vendedores de suministros de pesca."] = "Du hast keine Köder mehr, die du benutzen kannst. Händler für Angelbedarf verkaufen sie.",
	["Ya puedes"] = "Schon möglich",
	["Ya puedes aprender %s con un instructor."] = "Du kannst %s schon bei einem Lehrer lernen.",
	["Ya puedes aprender el rango %s"] = "Du kannst jetzt den Rang %s lernen",
	["Ya puedes aprender una receta"] = "Du kannst jetzt ein Rezept lernen",
	["Ya puedes entregarla."] = "Du kannst sie jetzt abgeben.",
	["Ya puedes fabricar y ganar"] = "Jetzt herstellen und verdienen",
	["Ya puedes hacer venenos. Ponlos en tus armas: suman mucho daño."] = "Du kannst jetzt Gifte herstellen. Trag sie auf deine Waffen auf: Sie bringen viel Schaden.",
	["Ya puedes minar %s."] = "Du kannst jetzt %s abbauen.",
	["Ya puedes recoger %s."] = "Du kannst jetzt %s sammeln.",
	["Ya puedes salir del grupo: la guarida se queda contigo."] = "Du kannst die Gruppe jetzt verlassen: Der Bau bleibt bei dir.",
	["Ya puedes tomar %d de sus misiones."] = "Du kannst schon %d ihrer Quests annehmen.",
	["Ya respondiste todo. Va en tu reporte (/alfa reportar)."] = "Du hast alles beantwortet. Es kommt in deinen Bericht (/alfa reportar).",
	["Ya salió Alfa %s"] = "Alfa %s ist erschienen",
	["Ya salió una versión nueva de Alfa"] = "Eine neue Alfa-Version ist erschienen",
	["Ya se está buscando, espera un momento."] = "Die Suche läuft schon, warte einen Moment.",
	["Ya se hizo de noche, lobo. Me pongo tranquilita: aquí sigo contigo."] = "Es ist Nacht geworden, Wolf. Ich werde ganz ruhig: ich bin noch bei dir.",
	["Ya se lo compartiste hace un momento."] = "Du hast es gerade erst geteilt.",
	["Ya se usa: clic otra vez"] = "Schon belegt: noch mal klicken",
	["Ya seguías %d guías: quité la que tocaste hace más tiempo. Las que fijas en Planes nunca se quitan solas."] = "Du hast schon %d Guides verfolgt: Ich habe den entfernt, den du am längsten nicht angefasst hast. Die in Pläne angehefteten werden nie von selbst entfernt.",
	["Ya sigues %d guías"] = "Du verfolgst schon %d Guides",
	["Ya sigues %d guías y todas están fijadas. Suelta una en Planes y vuelve a intentar."] = "Du folgst schon %d Guides und alle sind angeheftet. Löse einen in Pläne und versuch es noch mal.",
	["Ya sigues %d guías y todas están fijadas: clic para ver tus planes"] = "Du folgst schon %d Guides und alle sind angeheftet: Klick, um deine Pläne zu sehen",
	["Ya sigues 6 guías: clic para ver lo que sigues y quitar alguna"] = "Du verfolgst schon 6 Guides: Klick, um sie zu sehen und einen zu entfernen",
	["Ya sigues el plan «%s»."] = "Du folgst jetzt dem Plan „%s“.",
	["Ya sigues la guía que te compartió %s."] = "Du folgst jetzt dem Leitfaden, den %s mit dir geteilt hat.",
	["Ya te conté todo lo que sé por ahora. Con clic derecho puedo empezar de nuevo."] = "Ich habe dir alles erzählt, was ich bisher weiß. Mit Rechtsklick kann ich von vorn anfangen.",
	["Ya te dejé prendido lo que le va a tu clase. Agrega o quita lo que quieras: nada de esto juega por ti."] = "Ich habe schon eingeschaltet, was zu deiner Klasse passt. Füg hinzu oder nimm weg, was du willst: Nichts davon spielt für dich.",
	["Ya te lo dije %d veces: no lo repito en esta sesión."] = "Ich habe es dir schon %d-mal gesagt: In dieser Sitzung wiederhole ich es nicht.",
	["Ya tenías este plan: %s."] = "Diesen Plan hattest du schon: %s.",
	["Ya terminaste Armas: estos puntos van a Furia por más golpe crítico."] = "Waffen ist fertig: Diese Punkte gehen in Furor für mehr kritische Treffer.",
	["Ya tienes %d conjuntos: olvida uno primero."] = "Du hast schon %d Sets: Vergiss zuerst eins.",
	["Ya tienes %d de %s. Te falta %d de %d materiales."] = "Du hast %d von %s. Es fehlt noch %d von %d Materialien.",
	["Ya tienes %d de %s. Te faltan %d de %d materiales."] = "Du hast %d %s. Dir fehlen %d von %d Materialien.",
