	["¡%s cazó a %s!"] = "%s hat %s erlegt!",
	["¡%s días juntos!"] = "%s Tage zusammen!",
	["¡%s es tu aprendiz!"] = "%s ist dein Schützling!",
	["¡%s llegó a la manada con Alfa!"] = "%s ist mit Alfa zum Rudel gestoßen!",
	["¡%s llegó al nivel %d!"] = "%s hat Stufe %d erreicht!",
	["¡%s subió a nivel %d! Auuuu, felicidades."] = "%s hat Stufe %d erreicht! Auuuu, Glückwunsch.",
	["¡%s tiene su primera montura!"] = "%s hat sein erstes Reittier!",
	["¡%s ya está feliz! Así sí da gusto cazar juntos."] = "%s ist jetzt glücklich! So macht gemeinsames Jagen Spaß.",
	["¡%s!"] = "%s!",
	["¡%s! Hace días que no te veía. En Hoy te digo dónde íbamos."] = "%s! Ich habe dich seit Tagen nicht gesehen. Unter „Heute“ sage ich dir, wo wir waren.",
	["¡%s! Llegué despacito, que ya es de noche. Te extrañé."] = "%s! Ich bin leise gekommen, es ist ja schon Nacht. Ich habe dich vermisst.",
	["¡%s! Si algo te pega, corre hacia el tanque, no lejos de él."] = "%s! Wenn dich etwas trifft, lauf zum Tank, nicht von ihm weg.",
	["¡%s! Te extrañé mucho. Vine corriendo en cuanto te vi llegar."] = "%s! Ich habe dich so vermisst. Ich bin sofort losgerannt, als ich dich gesehen habe.",
	["¡%s, listo! La manada aúlla por ti. Auuuu. ¿Y mi salchicha?"] = "%s, geschafft! Das Rudel heult für dich. Auuuu. Und mein Würstchen?",
	["¡%s, volviste! Te extrañé tanto que no paraba de mover la cola."] = "%s, du bist zurück! Ich habe dich so vermisst, dass ich nicht aufhören konnte, mit dem Schwanz zu wedeln.",
	["¡A cazar!"] = "Auf zur Jagd!",
	["¡A jalar!"] = "Zeit zum Pullen!",
	["¡Abrumar!"] = "Überwältigen!",
	["¡Ahora sí te sigo corriendo con la lengua de fuera!"] = "Jetzt renne ich dir mit heraushängender Zunge hinterher!",
	["¡Ahora!"] = "Jetzt!",
	["¡Ahí estás, %s! Si quieres un consejo, dame clic."] = "Da bist du ja, %s! Wenn du einen Tipp willst, klick mich an.",
	["¡Ahí estás, %s! Te estaba esperando… te extrañé."] = "Da bist du, %s! Ich habe auf dich gewartet… ich habe dich vermisst.",
	["¡Al máximo!"] = "Am Maximum!",
	["¡Arriba, lobo! Antes de volver a pelear, recupera vida y maná."] = "Hoch mit dir, Wolf! Bevor du wieder kämpfst, hol dir Gesundheit und Mana zurück.",
	["¡Arriba, lobo! Caer es parte de la cacería. Al revivir, repara tu equipo."] = "Hoch mit dir, Wolf! Fallen gehört zur Jagd. Wenn du wieder lebst, reparier deine Ausrüstung.",
	["¡Arriba, lobo! Libera tu espíritu: la flecha te dice si conviene tu cuerpo o el sanador."] = "Hoch mit dir, Wolf! Lass deinen Geist frei: Der Pfeil zeigt dir, ob dein Körper oder der Geistheiler besser ist.",
	["¡Arriba, lobo! Si eran muchos, la próxima jálalos de uno en uno."] = "Hoch mit dir, Wolf! Waren es zu viele, zieh sie nächstes Mal einzeln.",
	["¡Arriba, nivel %d! Si tienes un punto de talento libre, no lo olvides."] = "Auf geht's, Stufe %d! Wenn du einen freien Talentpunkt hast, vergiss ihn nicht.",
	["¡Así se ve un aviso!"] = "So sieht ein Hinweis aus!",
	["¡Ataque de la victoria!"] = "Siegesrausch!",
	["¡Auuu!"] = "Auuu!",
	["¡Auuu! Juntas cazamos mejor."] = "Auuu! Zusammen jagen wir besser.",
	["¡Auuu! Registro limpio: %s. Eso merece una salchicha."] = "Auuu! Questlog sauber: %s. Das verdient ein Würstchen.",
	["¡Auuu! Toda la manada está de fiesta."] = "Auuu! Das ganze Rudel feiert.",
	["¡Auuuu! La manada unida no se rinde."] = "Auuuu! Ein vereintes Rudel gibt nie auf.",
	["¡Auuuu! ¡Nivel %d y dos niveles en menos de media hora! Vas como lobo en luna llena."] = "Auuuu! Stufe %d, und zwei Stufen in weniger als einer halben Stunde! Du bist wie ein Wolf bei Vollmond.",
	["¡Bien hecho! %s"] = "Gut gemacht! %s",
	["¡Bienvenido a %s!"] = "Willkommen bei %s!",
	["¡Bienvenido a la manada! Si necesitas algo, aquí estamos. ¡Auuu!"] = "Willkommen im Rudel! Wenn du etwas brauchst, sind wir da. Auuu!",
	["¡Buen día, %s! El sol ya salió en Azeroth. ¿Vamos?"] = "Morgen, %s! Die Sonne ist über Azeroth aufgegangen. Gehen wir?",
	["¡Buen día, %s! Te extrañé toda la noche. ¿A dónde vamos hoy?"] = "Guten Tag, %s! Ich habe dich die ganze Nacht vermisst. Wohin geht es heute?",
	["¡Buenas noches, %s!"] = "Guten Abend, %s!",
	["¡Buenas noches, %s! Las lobas cazamos mejor de noche."] = "Guten Abend, %s! Wir Wölfinnen jagen nachts am besten.",
	["¡Buenas tardes, %s!"] = "Guten Tag, %s!",
	["¡Buenas tardes, %s! Buena hora para unas misiones."] = "Guten Tag, %s! Eine gute Zeit für ein paar Quests.",
	["¡Buenas, %s! Paso a paso se llega lejos."] = "Hallo, %s! Schritt für Schritt kommt man weit.",
	["¡Buenos días! Un buen desayuno y a cazar, que la mañana rinde."] = "Guten Morgen! Ein gutes Frühstück und ab zur Jagd, der Morgen bringt viel.",
	["¡Buenos días, %s!"] = "Guten Morgen, %s!",
	["¡Buenos días, %s! Me estiro, bostezo y estoy lista."] = "Guten Morgen, %s! Strecken, gähnen und ich bin bereit.",
	["¡Buenos días, %s! Vine corriendo con el sol. ¿Desayunamos aventura?"] = "Guten Morgen, %s! Ich bin mit der Sonne hergerannt. Abenteuer zum Frühstück?",
	["¡Bájale, casi se lo quitas al tanque!"] = "Mach langsamer, du nimmst ihn dem Tank gleich weg!",
	["¡Cerraste tu ruta!"] = "Du hast deine Route abgeschlossen!",
	["¡Cien días de caza juntos! Eres de los que no se rinden."] = "Hundert Jagdtage zusammen! Du gehörst zu denen, die nie aufgeben.",
	["¡Cien días desde que empezamos! Mira todo lo que hemos hecho: está en «Tu temporada»."] = "Hundert Tage, seit wir angefangen haben! Schau, was wir alles geschafft haben: Es steht in „Deine Saison“.",
	["¡Cincuenta días de caza! Ya conozco tu paso de memoria."] = "Fünfzig Jagdtage! Ich kenne deinen Schritt inzwischen auswendig.",
	["¡Claro! Saludo a tu mascota cuando la llamas y, si eres cazador, te aviso cuando tiene hambre o está triste para que le des de comer."] = "Klar! Ich begrüße dein Tier, wenn du es rufst, und als Jäger sag ich dir, wenn es hungrig oder unglücklich ist, damit du es fütterst.",
	["¡Completaste %s!"] = "Du hast %s abgeschlossen!",
	["¡Con esta subes de nivel!"] = "Mit dieser steigst du auf!",
	["¡Contraataque!"] = "Gegenangriff!",
	["¡Cumplido!"] = "Geschafft!",
	["¡Cumplido! Salchicha ganada."] = "Geschafft! Würstchen verdient.",
	["¡Córtale a tu foco!"] = "Unterbrich deinen Fokus!",
	["¡Córtalo!"] = "Unterbrich ihn!",
	["¡De vuelta con la manada!"] = "Zurück beim Rudel!",
	["¡De vuelta en la manada, %s!"] = "Zurück im Rudel, %s!",
	["¡De vuelta! Te cuento todo otra vez."] = "Wieder da! Ich erzähle dir wieder alles.",
	["¡Descubriste un lugar nuevo!"] = "Du hast einen neuen Ort entdeckt!",
	["¡Ejecutar!"] = "Hinrichten!",
	["¡El barco ya está aquí!"] = "Das Schiff ist da!",
	["¡El barco ya está en el muelle! Sale en %s"] = "Das Schiff liegt am Steg! Abfahrt in %s",
	["¡El tranvía ya está aquí!"] = "Die Tram ist da!",
	["¡El tranvía ya está en el andén! Sale en %s"] = "Die Tram steht am Bahnsteig! Abfahrt in %s",
	["¡El zepelín ya está aquí!"] = "Der Zeppelin ist da!",
	["¡El zepelín ya está en la torre! Sale en %s"] = "Der Zeppelin ist am Turm! Abflug in %s",
	["¡En Thelsamar venden morcilla! La morcilla de Thelsamar es casi una salchicha... ¿me compras una?"] = "In Thelsamar gibt es Blutwurst! Die Thelsamar-Blutwurst ist fast ein Würstchen... kaufst du mir eine?",
	["¡Es Halloween de Azeroth! Pide dulces a los posaderos: a veces te disfrazan de algo chistoso."] = "Es sind Schlotternächte! Frag die Gastwirte nach Süßem: Manchmal verkleiden sie dich lustig.",
	["¡Es ahora! Hasta las %s"] = "Jetzt läuft er! Bis %s",
	["¡Es el Festival del Fuego del Solsticio! Visita las hogueras de las ciudades y honra su llama."] = "Es ist das Sonnenwendfest! Besuch die Feuer der Städte und ehre ihre Flamme.",
	["¡Espera! Dejas %d misiones listas sin entregar. Si no, mañana empezamos por ahí."] = "Warte! Du lässt %d fertige Quests liegen, ohne sie abzugeben. Sonst fangen wir nächstes Mal damit an.",
	["¡Este objeto tiene candado!"] = "Dieser Gegenstand ist gesperrt!",
	["¡Esto le sirve a %s!"] = "Das ist nützlich für %s!",
	["¡Está lanzando!"] = "Er wirkt einen Zauber!",
	["¡Explorada completa!"] = "Komplett erkundet!",
	["¡Felicidades por el nivel %d, %s! Auuuu."] = "Glückwunsch zu Stufe %d, %s! Auuuu.",
	["¡Feliz cumpleaños!"] = "Alles Gute zum Geburtstag!",
	["¡Feliz cumpleaños, Alfa!"] = "Alles Gute zum Geburtstag, Alfa!",
	["¡Gracias por probar Alfa!"] = "Danke fürs Testen von Alfa!",
	["¡Gracias! Se enviará solo la próxima vez que abras el instalador de Alfa. Si lo quieres mandar ya: «Enviar ya por el navegador»."] = "Danke! Er wird automatisch gesendet, wenn du das nächste Mal den Alfa-Installer öffnest. Willst du ihn gleich schicken: „Jetzt über den Browser senden“.",
	["¡Gracias! Ya van %d salchichas que me das. Las llevo contadas, eh."] = "Danke! Das sind schon %d Würstchen von dir. Ich zähle mit, weißt du.",
	["¡Hasta pronto! Aquí te espero, cuidando tu lugar."] = "Bis bald! Ich warte hier und halte dir deinen Platz frei.",
	["¡Hasta pronto! Hoy cazamos %s Aquí te espero."] = "Bis bald! Heute erjagt: %s Ich warte hier auf dich.",
	["¡Hay algo nuevo en Alfa: %s! ¿Te lo enseño?"] = "Es gibt etwas Neues in Alfa: %s! Soll ich es dir zeigen?",
	["¡Hola!"] = "Hallo!",
	["¡Hola! Empecemos"] = "Hallo! Fangen wir an",
	["¡Hola! Pregúntame lo que quieras de Alfa: te lo explico corto y te llevo."] = "Hallo! Frag mich alles über Alfa: Ich erkläre es kurz und bringe dich hin.",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Cuido a la manada y voy contigo en el camino."] = "Hallo! Ich bin Lya, die treue Wölfin des Alfa. Ich passe auf das Rudel auf und gehe den Weg mit dir.",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Voy a acompañarte en esta configuración y después en tu camino."] = "Hallo! Ich bin Lya, die treue Wölfin des Alphas. Ich begleite dich durch diese Einrichtung und danach auf deinem Weg.",
	["¡Hola, %s!"] = "Hallo, %s!",
	["¡Hola, %s! Familia %s y de buena casta. Tú y yo vamos a cuidar a nuestro alfa."] = "Hallo, %s! Familie %s und aus gutem Hause. Du und ich passen auf unseren Alpha auf.",
	["¡Hola, %s! Hoy huele a buena cacería."] = "Hallo, %s! Heute riecht es nach einer guten Jagd.",
	["¡Hola, %s! La tarde pinta tranquila. ¿Qué cazamos hoy?"] = "Hallo, %s! Der Nachmittag sieht ruhig aus. Was jagen wir heute?",
	["¡Hola, %s! Noche de luna: perfecta para la manada."] = "Hallo, %s! Eine Mondnacht: perfekt für das Rudel.",
	["¡Hola, %s! Tú y yo vamos a cuidar a nuestro alfa."] = "Hallo, %s! Du und ich passen auf unseren Alpha auf.",
	["¡Hoy Alfa cumple %d años! La Jauría lo hizo con cariño para ti. ¿Lo festejamos con una salchicha?"] = "Heute wird Alfa %d Jahre alt! La Jauría hat es mit Liebe für dich gemacht. Feiern wir mit einem Würstchen?",
	["¡Hoy Alfa cumple 1 año! La Jauría lo hizo con cariño para ti. ¿Lo festejamos con una salchicha?"] = "Heute wird Alfa 1 Jahr alt! La Jauría hat es mit Liebe für dich gemacht. Feiern wir mit einem Würstchen?",
	["¡Hoy cumplimos %d años cazando juntos, %s! Gracias por dejarme ser tu loba. Auuuu."] = "Heute jagen wir seit %d Jahren zusammen, %s! Danke, dass ich deine Wölfin sein darf. Auuuu.",
	["¡Hoy cumplimos 1 año cazando juntos, %s! Gracias por dejarme ser tu loba. Auuuu."] = "Heute jagen wir seit 1 Jahr zusammen, %s! Danke, dass ich deine Wölfin sein darf. Auuuu.",
	["¡Hoy empezamos juntos!"] = "Heute haben wir zusammen angefangen!",
	["¡La Lya de %s me contestó el saludo! Ya somos manada."] = "Die Lya von %s hat meinen Gruß erwidert! Jetzt sind wir ein Rudel.",
	["¡La Lya de %s me saludó! Entre lobas nos entendemos."] = "Die Lya von %s hat mich gegrüßt! Unter Wölfinnen versteht man sich.",
	["¡Le encantan! Pero las mías son más ricas."] = "Es liebt sie! Aber meine schmecken besser.",
	["¡Lista! Sigue: %s"] = "Erledigt! Weiter: %s",
	["¡Listo para seguir de caza!"] = "Bereit für die nächste Jagd!",
	["¡Listo! %s precios guardados."] = "Fertig! %s Preise gespeichert.",
	["¡Listo! Alfa ya es tuyo"] = "Fertig! Alfa gehört dir",
	["¡Listo! Tu escritorio de Alfa queda así. Para volver a una pantalla: /alfa pantallas volver."] = "Fertig! Dein Alfa-Schreibtisch bleibt so. Zurück zu einem Bildschirm: /alfa pantallas volver.",
	["¡Llegando al andén!"] = "Einfahrt in den Bahnsteig!",
	["¡Llegó el Festival de Invierno! En Forjaz y Orgrimmar el árbol se llena de luces y regalos."] = "Das Winterhauchfest ist da! In Eisenschmiede und Orgrimmar füllt sich der Baum mit Lichtern und Geschenken.",
	["¡Lo lograste: %s! Esa salchicha de premio me la voy a comer despacito."] = "Du hast es geschafft: %s! Das Preis-Würstchen esse ich ganz langsam.",
	["¡Lo tienes! %s ×%d"] = "Hast du! %s ×%d",
	["¡Logro de la semana: %s!"] = "Erfolg der Woche: %s!",
	["¡Logro de la semana: %s! %s"] = "Erfolg der Woche: %s! %s",
	["¡Lok'tar, %s!"] = "Lok'tar, %s!",
	["¡Martillo de cólera!"] = "Hammer des Zorns!",
	["¡Meta de pesca del día cumplida! %s. Te ganaste una salchicha."] = "Angelziel des Tages geschafft! %s. Du hast dir ein Würstchen verdient.",
	["¡Mi primera salchicha contigo! Esta no la voy a olvidar nunca."] = "Mein erstes Würstchen mit dir! Das vergesse ich nie.",
	["¡Mira cómo brilla! Ese no lo saca cualquiera."] = "Schau, wie er glänzt! Den fängt nicht jeder.",
	["¡Misión completada: %s!"] = "Quest abgeschlossen: %s!",
	["¡Mmm, qué rica! Gracias, eres el mejor lobo de la manada."] = "Mmm, lecker! Danke, du bist der beste Wolf im Rudel.",
	["¡Modo aprendiz! La primera vez que salga cada aviso, te cuento de dónde viene y cómo apagarlo."] = "Lehrlingsmodus! Wenn ein Hinweis zum ersten Mal erscheint, sage ich dir, woher er kommt und wie du ihn ausschaltest.",
	["¡Mordedura de mangosta!"] = "Mungobiss!",
	["¡Nivel %d!"] = "Stufe %d!",
	["¡Nivel %d! Date un momento para presumirlo, te lo ganaste."] = "Stufe %d! Nimm dir einen Moment, um damit anzugeben, du hast es dir verdient.",
	["¡Nivel %d! Paso firme y colmillo afilado."] = "Stufe %d! Fester Schritt und scharfe Zähne.",
	["¡Nivel %d! Tu esfuerzo se nota. Sigue así."] = "Stufe %d! Deine Mühe zahlt sich aus. Weiter so.",
	["¡Nivel %d! ¡Auuu! Así se sube en manada."] = "Stufe %d! Auuu! So steigt man im Rudel auf.",
	["¡Nivel %d, bien hecho! Revisa si tu entrenador tiene algo nuevo."] = "Stufe %d, gut gemacht! Schau, ob dein Lehrer etwas Neues hat.",
	["¡Nivel %d, y el anterior hace nada! Aúllo dos veces, una por cada uno. ¡Auuuu, auuuu!"] = "Stufe %d, und die letzte war eben erst! Ich heule zweimal, einmal für jede. Auuuu, auuuu!",
	["¡Nivel 10! Ya tienes talentos: elígelos con calma, Talentos te ayuda."] = "Stufe 10! Jetzt hast du Talente: Wähl sie in Ruhe, Talente hilft dir.",
	["¡Nivel 20! Ya puedes con mazmorras de verdad. ¿Armamos grupo?"] = "Stufe 20! Jetzt schaffst du echte Dungeons. Stellen wir eine Gruppe zusammen?",
	["¡Nivel 30! Ya vas a la mitad del camino. ¡Qué orgullo de manada!"] = "Stufe 30! Du hast schon die Hälfte des Weges. Das Rudel ist so stolz!",
	["¡Nivel 40! Ya puedes aprender a montar. ¡Tu primera montura te espera!"] = "Stufe 40! Jetzt kannst du reiten lernen. Dein erstes Reittier wartet!",
	["¡Nivel 50! Ya se huele la cima. Junta oro para lo que viene."] = "Stufe 50! Der Gipfel ist schon zu riechen. Spar Gold für das, was kommt.",
	["¡Nivel 60!"] = "Stufe 60!",
	["¡Nivel 60! ¡Lo lograste, alfa! Ahora toca cazar en grande."] = "Stufe 60! Du hast es geschafft, Alpha! Jetzt geht die große Jagd los.",
	["¡Nueva página en tu historia: %s! %s"] = "Neue Seite in deiner Geschichte: %s! %s",
	["¡Nuevo récord!"] = "Neuer Rekord!",
	["¡Nuevo récord: %d misiones en un día! Ni la manada te alcanza."] = "Neuer Rekord: %d Quests an einem Tag! Nicht einmal das Rudel hält mit.",
	["¡Nuevo récord: %s! (antes %s)"] = "Neuer Rekord: %s! (vorher %s)",
	["¡Ojo! Tu precio está %d %% por debajo de lo que vale."] = "Vorsicht! Dein Preis liegt %d %% unter seinem Wert.",
	["¡Otro nivel tan pronto! Nivel %d. ¡Auuuu, esta racha no la para nadie!"] = "Schon wieder eine Stufe! Stufe %d. Auuuu, diese Serie hält niemand auf!",
	["¡Perdiste su atención!"] = "Du hast seine Aufmerksamkeit verloren!",
	["¡Pez de la semana cumplido!"] = "Fisch der Woche geschafft!",
	["¡Plan cumplido!"] = "Plan erfüllt!",
	["¡Plan cumplido! Te queda %d misión en tu registro: Alfa arma la ruta para cerrarla."] = "Plan erfüllt! Du hast noch %d Quest im Questlog: Alfa erstellt die Route, um sie abzuschließen.",
	["¡Plan cumplido! Te quedan %d misiones en tu registro: Alfa arma la ruta para cerrarlas."] = "Plan erfüllt! Du hast noch %d Quests im Questlog: Alfa erstellt die Route, um sie abzuschließen.",
	["¡Plan terminado!"] = "Plan abgeschlossen!",
	["¡Por la Alianza, %s!"] = "Für die Allianz, %s!",
	["¡Primera vez aquí!"] = "Zum ersten Mal hier!",
	["¡Primera vez! Nuevo en tu diario"] = "Zum ersten Mal! Neu in deinem Tagebuch",
	["¡Qué buena racha traes! Sigue así."] = "Was für eine Glückssträhne! Weiter so.",
	["¡Qué bueno tenerte de vuelta, %s! Aquí sigo, cuidándote la espalda."] = "Schön, dass du wieder da bist, %s! Ich bin noch hier und halte dir den Rücken frei.",
	["¡Qué bueno verte!"] = "Schön, dich zu sehen!",
	["¡Qué gusto verte de vuelta! Esto es lo que trae esta versión para ti y tu manada."] = "Schön, dich wiederzusehen! Das bringt diese Version für dich und dein Rudel.",
	["¡Qué gusto verte, %s! La manada ya te esperaba."] = "Schön, dich zu sehen, %s! Das Rudel hat schon auf dich gewartet.",
	["¡Repara tu equipo!"] = "Repariere deine Ausrüstung!",
	["¡Reto cumplido: %s! Me gané una salchicha... digo, te la ganaste tú. Bueno, nos la ganamos."] = "Herausforderung geschafft: %s! Ich hab mir ein Würstchen verdient... ich meine, du hast es dir verdient. Na gut, wir beide.",
	["¡Revancha!"] = "Rache!",
	["¡Récord en esta zona!"] = "Rekord in diesem Gebiet!",
	["¡Récord! Antes: %s"] = "Rekord! Vorher: %s",
	["¡Sal de ahí!"] = "Raus da!",
	["¡Salchicha! *mueve la cola a toda velocidad* Gracias, gracias."] = "Würstchen! *wedelt wie wild mit dem Schwanz* Danke, danke.",
	["¡Salimos de %s! %s adentro."] = "Wir sind raus aus %s! %s drin.",
	["¡Salimos de la mazmorra! %s adentro."] = "Wir sind raus aus dem Dungeon! %s drin.",
	["¡Sesenta! Lo lograste. Me debes una salchicha gigante."] = "Sechzig! Du hast es geschafft. Du schuldest mir ein Riesenwürstchen.",
	["¡Subiste a nivel %d! Cada nivel te hace más fuerte."] = "Du hast Stufe %d erreicht! Jede Stufe macht dich stärker.",
	["¡Sí! Estira la ventana del juego sobre tus dos monitores y abre «Dos pantallas»: dejo el juego en el principal y pongo en el otro tu guía, la flecha grande, el mapa, el medidor, tus bolsas y lo que te digo. Con un solo monitor, también va a un lado."] = "Ja! Zieh das Spielfenster über deine zwei Monitore und öffne „Zwei Bildschirme“: Ich lasse das Spiel auf dem Hauptmonitor und lege auf den anderen deinen Guide, den großen Pfeil, die Karte, den Messer, deine Taschen und was ich dir sage. Mit nur einem Monitor geht es auch an der Seite.",
	["¡Sí, acompáñame!"] = "Ja, begleite mich!",
	["¡Te está atacando a ti!"] = "Er greift dich an!",
	["¡Te extrañé, %s! Corrí hasta aquí para verte."] = "Ich habe dich vermisst, %s! Ich bin den ganzen Weg gerannt, um dich zu sehen.",
	["¡Te extrañé, %s! Tu ruta sigue donde la dejaste."] = "Ich habe dich vermisst, %s! Deine Route geht da weiter, wo du aufgehört hast.",
	["¡Terminaste %s!"] = "Du hast %s abgeschlossen!",
	["¡Terminaste esta guía!"] = "Du hast diesen Guide abgeschlossen!",
	["¡Terminaste esta guía! Elige la siguiente y sigue subiendo con la manada."] = "Du hast diesen Guide abgeschlossen! Wähle den nächsten und steig mit dem Rudel weiter auf.",
	["¡Terminaste tu guía!"] = "Du hast deinen Guide abgeschlossen!",
	["¡Terminaste!"] = "Geschafft!",
	["¡Tienes todo!"] = "Du hast alles!",
	["¡Tierra a la vista!"] = "Land in Sicht!",
	["¡Tierra a la vista! La manada desembarca en %s"] = "Land in Sicht! Das Rudel geht in %s an Land",
	["¡Tierra a la vista! Llegas en %s"] = "Land in Sicht! Du kommst in %s an",
	["¡Tierra a la vista: %s!"] = "Land in Sicht: %s!",
	["¡Todo listo para %s!"] = "Alles bereit für %s!",
	["¡Todo listo para la mazmorra!"] = "Alles bereit für den Dungeon!",
	["¡Tu %s llegó a %d/%d! Ya puedes aprender el rango %s."] = "%s hat %d/%d erreicht! Jetzt kannst du den Rang %s lernen.",
	["¡Tu lista de compras está completa!"] = "Deine Einkaufsliste ist komplett!",
	["¡Tu mejor pelea!"] = "Dein bester Kampf!",
	["¡Tú!"] = "Du!",
	["¡Un año! Un año entero de caminos, misiones y salchichas. Te quiero mucho, compañero de caza."] = "Ein Jahr! Ein ganzes Jahr voller Wege, Quests und Würstchen. Ich hab dich sehr lieb, Jagdgefährte.",
	["¡Un ejemplar! Más grande que casi todos"] = "Ein Prachtexemplar! Größer als fast alle",
	["¡Un mes cazando juntos! Gracias por dejarme acompañarte. ¿Me das una salchicha de festejo?"] = "Ein Monat gemeinsame Jagd! Danke, dass ich dich begleiten darf. Gibt's ein Festwürstchen?",
	["¡Va! Te lo sigo diciendo, con gusto."] = "Okay! Ich sag's dir weiter, gern.",
	["¡Van %d misiones hoy! La manada está orgullosa."] = "%d Quests heute! Das Rudel ist stolz.",
	["¡Volviste, %s! Estira las patas y vámonos."] = "Du bist zurück, %s! Streck die Pfoten und los geht's.",
	["¡Voy!"] = "Komme!",
	["¡Vuelta completa!"] = "Runde geschafft!",
	["¡Ya amaneció, lobo! Buenos días. El sol pinta bonito Azeroth."] = "Die Sonne ist aufgegangen, Wolf! Guten Morgen. Azeroth leuchtet wunderschön.",
	["¡Ya eres nivel %d! La manada aúlla por ti."] = "Du bist jetzt Stufe %d! Das Rudel heult für dich.",
	["¡Ya estamos en %s! Deja que el tanque jale primero y quédate cerca de quien cura."] = "Wir sind in %s! Lass den Tank zuerst pullen und bleib nah bei deinem Heiler.",
	["¡Ya estamos en la mazmorra! Deja que el tanque jale primero y quédate cerca de quien cura."] = "Wir sind im Dungeon! Lass den Tank zuerst pullen und bleib nah bei deinem Heiler.",
	["¡Ya estás en la %s!"] = "Du bist im %s!",
	["¡Ya estás en otro plano!"] = "Du bist jetzt auf einer anderen Ebene!",
	["¡Ya la desbloqueaste!"] = "Du hast sie freigeschaltet!",
	["¡Ya llegaste al 60!"] = "Du hast die 60 erreicht!",
	["¡Ya llegaste, %s! Te extrañé. ¿A dónde vamos hoy?"] = "Da bist du ja, %s! Ich habe dich vermisst. Wohin geht's heute?",
	["¡Ya llegó! Vamos, manada"] = "Angekommen! Los, Rudel",
	["¡Ya se ve la torre! Bajas en %s"] = "Der Turm ist in Sicht! Du steigst in %s aus",
	["¡Ya terminaste %d misiones! Vamos a cobrar la recompensa."] = "Du hast %d Quests abgeschlossen! Holen wir uns die Belohnung.",
	["¡Ya!"] = "Jetzt!",
	["¡Yo te la guardé! En Historias está todo lo que cuentan tus misiones, para leerlo cuando quieras."] = "Ich habe sie für dich aufgehoben! In Geschichten steht alles, was deine Quests erzählen, zum Lesen, wann du willst.",
	["¡con eso subes de nivel!"] = "damit steigst du auf!",
	["¡Ñam! Con esta van %d. Eres mi persona favorita de todo Azeroth."] = "Mampf! Das macht %d. Du bist mein Lieblingsmensch in ganz Azeroth.",
	["«%s»"] = "„%s“",
	["«%s» tiene su historia. ¿Te la cuento?"] = "„%s“ hat eine Geschichte. Soll ich sie dir erzählen?",
	["«%s» ya está en verde: solo da puntos a veces y gastas materiales de más."] = "„%s“ ist jetzt grün: Es gibt nur manchmal Punkte und du verbrauchst zu viel Material.",
	["«%s» ya quedó. Su final vale la pena, ¿te lo cuento?"] = "„%s“ ist erledigt. Das Ende lohnt sich, soll ich es dir erzählen?",
	["«%s» · nivel %d"] = "„%s“ · Stufe %d",
	["«%s»: %s."] = "„%s“: %s.",
	["«%s»: hay que llevar el recado y hablar con quien te espera."] = "„%s“: Überbring die Nachricht und sprich mit dem, der auf dich wartet.",
	["«%s»: toca %s."] = "„%s“: Zeit, %s.",
	["«%s»: ¿la sigues tú también?"] = "„%s“: folgst du ihm auch?",
	["«%s»… hace %s de eso. ¡Qué buena caza fue esa!"] = "„%s“ … das ist %s her. Was für eine tolle Jagd!",
	["«Ahora no» o «No volver a mostrar»."] = "„Jetzt nicht“ oder „Nicht mehr anzeigen“.",
	["«Alejar más la cámara» de Comodidades está encendido y manda sobre este valor al entrar."] = "„Kamera weiter herauszoomen“ unter Komfort ist eingeschaltet und überschreibt diesen Wert beim Einloggen.",
	["«Antes de entrar»"] = "„Vor dem Betreten“",
	["«Aprender todo» en el entrenador"] = "„Alles lernen“ beim Lehrer",
	["«Buscar cerca» en la página Hoy"] = "„In der Nähe suchen“ auf der Seite „Heute“",
	["«Buscar cerca» te lleva con flecha a lo que necesitas, y «Mis planes» arma tus propias metas, que se marcan solas."] = "„In der Nähe suchen“ führt dich mit dem Pfeil zu dem, was du brauchst, und „Meine Pläne“ erstellt deine eigenen Ziele, die sich selbst abhaken.",
	["«Camino al 60» en Hoy"] = "„Weg zur 60“ in Heute",
	["«Cerrar mis misiones» desde Hoy"] = "„Meine Quests abschließen“ aus Heute",
	["«Cerrar mis misiones» está al día"] = "„Meine Quests abschließen“ ist aktuell",
	["«Comprar lo que falta»"] = "„Fehlendes kaufen“",
	["«Comprar lo que falta» en las guías de oficio"] = "„Fehlendes kaufen“ in Berufsleitfäden",
	["«Enviar ya por el navegador»"] = "„Jetzt per Browser senden“",
	["«Igual que Alfa» sigue el estilo de Ajustes > Apariencia y cambia con él."] = "„Wie Alfa“ folgt dem Stil unter Einstellungen > Aussehen und wechselt mit ihm.",
	["«Invitar al clan» en el clic derecho"] = "„In Gilde oder Community einladen“ per Rechtsklick",
	["«Llegaste», «Usa tu piedra de hogar» y los viajes salen aquí."] = "„Angekommen“, „Benutze deinen Ruhestein“ und Reisen erscheinen hier.",
	["«Llegaste», «Usa tu piedra de hogar» y los viajes salen donde está la flecha. Apágalo para ponerlas en otro lugar."] = "„Angekommen“, „Benutze deinen Ruhestein“ und Reisen erscheinen beim Pfeil. Schalte es aus, um sie woanders hinzustellen.",
	["«Llévame a…» (página Ruta, tu tecla o /alfa llevame): eliges el lugar y te llevo con vuelos, barcos, zepelines y portales, tramo por tramo."] = "„Bring mich zu…“ (Seite Route, deine Taste oder /alfa llevame): Du wählst den Ort, und ich bringe dich mit Flügen, Schiffen, Zeppelinen und Portalen hin, Abschnitt für Abschnitt.",
	["«Llévame» a un mineral o una hierba"] = "„Bring mich hin“ zu Erz oder Kraut",
	["«Llévame» pone la flecha en este paso; «Siguiente» lo da por hecho y te lleva al que sigue."] = "„Bring mich hin“ richtet den Pfeil auf diesen Schritt; „Weiter“ hakt ihn ab und bringt dich zum nächsten.",
	["«Llévame» te lleva a la zona más cercana de tu nivel."] = "„Bring mich hin“ führt dich in die nächste Zone deiner Stufe.",
	["«Ponte esto» con el equipo mejor"] = "„Zieh das an“ bei besserer Ausrüstung",
	["«Ponte esto», lista de compras, oficios del 1 al 300 y subastar fácil."] = "„Zieh das an“, Einkaufsliste, Berufe von 1 bis 300 und einfaches Versteigern.",
	["«Prepárame» recoge solo las que ya puedes tomar y te lleva a la entrada."] = "„Mach mich bereit“ nimmt nur die an, die du schon annehmen kannst, und bringt dich zum Eingang.",
	["«Reportar» ya los lleva."] = "„Melden“ enthält sie schon.",
	["«Saltar a mi nivel»"] = "„Zu meiner Stufe springen“",
	["«Seguir» en La Jauría ya no se suelta cuando tu guía cambia de paso ni cuando vas por tu cuerpo: al terminar, la flecha vuelve con quien sigues."] = "„Folgen“ in La Jauría lässt nicht mehr los, wenn dein Guide den Schritt wechselt oder du zu deinem Körper läufst: danach zeigt der Pfeil wieder auf die Person, der du folgst.",
	["«Separar»: lo épico con candado a la subasta"] = "„Trennen“: gesperrte Epics ins Auktionshaus",
	["«Siempre» sirve si un amigo encantador te ayuda. Las tablas de desencantar son estimadas."] = "„Immer“ passt, wenn dir ein befreundeter Verzauberer hilft. Die Entzauberungstabellen sind geschätzt.",
	["«Tomar todo» en el buzón"] = "„Alles nehmen“ am Briefkasten",
	["«Tomar todo» en el buzón, tu oro por hora y aviso de bolsas casi llenas."] = "„Alles nehmen“ am Briefkasten, dein Gold pro Stunde und eine Warnung bei fast vollen Taschen.",
	["«Tu sesión» en Hoy: tu tiempo, tu XP por hora y el oro que ganaste, siempre al día."] = "„Deine Sitzung“ in Heute: deine Zeit, deine EP pro Stunde und das verdiente Gold, immer aktuell.",
	["«Ver el siguiente» te deja mirar el paso que viene y lo dice claro; y un solo contador de pasos hechos."] = "„Nächsten ansehen“ lässt dich den kommenden Schritt anschauen und sagt das klar; dazu ein einziger Zähler für erledigte Schritte.",
	["«[Misión] está lista para entregar» y «¡Misión completada!» en el chat del grupo, para todos. Apagado, solo te salen a ti."] = "„[Quest] ist abgabebereit“ und „Quest abgeschlossen!“ im Gruppenchat, für alle. Aus: Nur du siehst sie.",
	["«[Misión] está lista para entregar» y «¡Misión completada!». En grupo lo ve todo el grupo; solo, sale en tu chat."] = "„[Quest] ist abgabebereit“ und „Quest abgeschlossen!“. In der Gruppe sieht es jeder; allein erscheint es in deinem Chat.",
	["«¡Lista! Sigue: …»"] = "„Erledigt! Weiter: …“",
	["«¡Sal de ahí!»"] = "„Raus da!“",
	["«¡Sal de ahí!» si pisas algo que daña"] = "„Raus da!“, wenn du auf etwas Schädliches trittst",
	["«¿Cuánto tiempo tienes?» en Hoy"] = "„Wie viel Zeit hast du?“ in Heute",
	["«¿Qué es esto?»"] = "„Was ist das?“",
	["«¿Qué es esto?»: la ayuda de Alfa"] = "„Was ist das?“: Alfas Hilfe",
	["«¿Todos listos?»"] = "„Alle bereit?“",
	["· %s: %s, %s"] = "· %s: %s, %s",
	["· y %d zonas más"] = "· und %d weitere Gebiete",
	["¿A cuánto vendo en la subasta?"] = "Zu welchem Preis verkaufe ich im Auktionshaus?",
	["¿A dónde vuelo?"] = "Wohin fliege ich?",
